type CustomFixtures = {
  authPage: Page;
};

export const test = base.extend<CustomFixtures>({
  authPage: async ({ page }, use) => {
    await page.goto('/');
    await page.evaluate(() => {
      localStorage.setItem('auth_token', 'enterprise_mock_jwt_token_12345');
    });
    
    // Hand over control to test
    await use(page);

    // Teardown
    await page.evaluate(() => localStorage.clear());
  }
});

